{
  "assessment": "Belgium's economic growth is sluggish at 0.8% with a budget deficit of 4.1% of GDP, requiring careful fiscal management. Legislative elections approach in March 2027, and legislative support stands at 49%, meaning we must shore up domestic stability and address regional grievances gently, particularly among Flemish populations seeking autonomy. We should also respond positively to Luxembourg's overture to strengthen regional ties within the EU framework.",
  "directives": [
    {
      "type": "trade_deal_accept",
      "target": "LUX",
      "amount": 0,
      "sub": "",
      "order": "Accept the trade and security cooperation proposal from Luxembourg."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 0,
      "sub": "infrastructure",
      "order": "Increase infrastructure investment slightly to stimulate growth and employment."
    },
    {
      "type": "monetary_policy",
      "target": null,
      "amount": -0.25,
      "sub": "",
      "order": "Lower the policy rate slightly to support economic growth and ease inflation pressures."
    }
  ],
  "cables": [
    {
      "to": "LUX",
      "private": true,
      "text": "We accept your proposal for deeper cooperation on trade and security and look forward to strengthening our bilateral ties."
    }
  ],
  "public_statement": "The Belgian government remains committed to fostering sustainable economic growth, fiscal responsibility, and deepening cooperation with our European partners to ensure long-term prosperity for all citizens.",
  "standing_orders": [
    {
      "when": "growth_below:1.0",
      "do": {
        "type": "set_spending",
        "target": null,
        "amount": 3.5,
        "sub": "infrastructure",
        "order": "Boost infrastructure spending if annualised growth falls below 1%."
      }
    }
  ],
  "detailed_report": "economy"
}
